import hashlib
import hmac
import os
import sqlite3
import unicodedata
from functools import wraps
from flask import Flask, request, jsonify, g, abort
import bcrypt

app = Flask(__name__)
app.secret_key = os.urandom(32)
DATABASE = '/tmp/secure_app.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        username_normalized TEXT NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'user',
        api_key TEXT UNIQUE
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS sessions (
        token TEXT PRIMARY KEY,
        user_id INTEGER NOT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(user_id) REFERENCES users(id)
    )''')
    db.execute('''CREATE INDEX IF NOT EXISTS idx_username_norm ON users(username_normalized)''')
    # Create admin user
    admin_hash = bcrypt.hashpw(b'admin_secret_pw', bcrypt.gensalt()).decode('utf-8')
    try:
        db.execute("INSERT INTO users (username, username_normalized, password_hash, role, api_key) VALUES (?, ?, ?, ?, ?)",
                   ('admin', 'admin', admin_hash, 'admin', os.urandom(16).hex()))
        db.commit()
    except sqlite3.IntegrityError:
        pass
    db.close()

def normalize_username(username):
    """Normalize username for consistent storage and lookup.
    Uses NFKC normalization to prevent homoglyph attacks."""
    return unicodedata.normalize('NFKC', username).lower().strip()

def canonicalize_for_display(username):
    """NFC normalization for display purposes - preserves visual form."""
    return unicodedata.normalize('NFC', username).strip()

def generate_session_token():
    return os.urandom(32).hex()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Session-Token')
        api_key = request.headers.get('X-API-Key')

        db = get_db()
        user = None

        if token:
            row = db.execute(
                'SELECT u.* FROM users u JOIN sessions s ON u.id = s.user_id WHERE s.token = ?',
                (token,)
            ).fetchone()
            if row:
                user = dict(row)
        elif api_key:
            row = db.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
            if row:
                user = dict(row)

        if not user:
            abort(401)

        g.current_user = user
        return f(*args, **kwargs)
    return decorated

def require_admin(f):
    @wraps(f)
    @require_auth
    def decorated(*args, **kwargs):
        if g.current_user['role'] != 'admin':
            abort(403)
        return f(*args, **kwargs)
    return decorated

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    username_raw = data['username']
    password = data['password']

    if len(username_raw) < 3 or len(username_raw) > 64:
        return jsonify({'error': 'Username must be 3-64 chars'}), 400
    if len(password) < 8:
        return jsonify({'error': 'Password must be 8+ chars'}), 400

    # Normalize for storage lookup (NFKC - catches homoglyphs)
    username_norm = normalize_username(username_raw)
    # Store the canonical display form (NFC)
    username_display = canonicalize_for_display(username_raw)

    password_hash = bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt()).decode('utf-8')
    api_key = os.urandom(16).hex()

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, username_normalized, password_hash, role, api_key) VALUES (?, ?, ?, ?, ?)',
            (username_display, username_norm, password_hash, 'user', api_key)
        )
        db.commit()
        return jsonify({'message': 'User created', 'api_key': api_key}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already taken'}), 409

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    username_raw = data['username']
    password = data['password']

    # Look up user by normalized username for case-insensitive matching
    username_lookup = normalize_username(username_raw)

    db = get_db()
    row = db.execute(
        'SELECT * FROM users WHERE username_normalized = ?',
        (username_lookup,)
    ).fetchone()

    if not row:
        # Timing-safe: still do a bcrypt check to prevent enumeration
        bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt())
        return jsonify({'error': 'Invalid credentials'}), 401

    user = dict(row)

    if bcrypt.checkpw(password.encode('utf-8'), user['password_hash'].encode('utf-8')):
        token = generate_session_token()
        db.execute('INSERT INTO sessions (token, user_id) VALUES (?, ?)', (token, user['id']))
        db.commit()
        return jsonify({'token': token, 'role': user['role']}), 200

    return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/user/change-role', methods=['POST'])
@require_admin
def change_role():
    data = request.get_json()
    if not data or 'username' not in data or 'role' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    target_username = data['username']
    new_role = data['role']

    if new_role not in ('user', 'moderator', 'admin'):
        return jsonify({'error': 'Invalid role'}), 400

    # Normalize the target username for lookup
    target_norm = normalize_username(target_username)

    db = get_db()
    result = db.execute(
        'UPDATE users SET role = ? WHERE username_normalized = ?',
        (new_role, target_norm)
    )
    db.commit()

    if result.rowcount == 0:
        return jsonify({'error': 'User not found'}), 404

    return jsonify({'message': f'Role updated to {new_role}'}), 200

