@app.route('/user/reset-password', methods=['POST'])
def reset_password():
    """Password reset - verifies identity via username + API key."""
    data = request.get_json()
    if not data or 'username' not in data or 'api_key' not in data or 'new_password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    username_raw = data['username']
    api_key = data['api_key']
    new_password = data['new_password']

    if len(new_password) < 8:
        return jsonify({'error': 'Password must be 8+ chars'}), 400

    # Use NFC normalization for the lookup (display form matching)
    username_canonical = canonicalize_for_display(username_raw)

    db = get_db()
    row = db.execute(
        'SELECT * FROM users WHERE username = ? AND api_key = ?',
        (username_canonical, api_key)
    ).fetchone()

    if not row:
        return jsonify({'error': 'Invalid username or API key'}), 401

    user = dict(row)
    new_hash = bcrypt.hashpw(new_password.encode('utf-8'), bcrypt.gensalt()).decode('utf-8')

    db.execute('UPDATE users SET password_hash = ? WHERE id = ?', (new_hash, user['id']))
    db.commit()

    return jsonify({'message': 'Password reset successful'}), 200

@app.route('/admin/users', methods=['GET'])
@require_admin
def list_users():
    db = get_db()
    rows = db.execute('SELECT id, username, role FROM users').fetchall()
    users = [dict(r) for r in rows]
    return jsonify({'users': users})

@app.route('/admin/delete-user', methods=['POST'])
@require_admin
def delete_user():
    data = request.get_json()
    if not data or 'username' not in data:
        return jsonify({'error': 'Missing username'}), 400

    target = data['username']
    target_norm = normalize_username(target)

    # Prevent self-deletion
    current_norm = normalize_username(g.current_user['username'])
    if target_norm == current_norm:
        return jsonify({'error': 'Cannot delete yourself'}), 400

    db = get_db()
    # Delete sessions first
    db.execute('DELETE FROM sessions WHERE user_id IN (SELECT id FROM users WHERE username_normalized = ?)', (target_norm,))
    result = db.execute('DELETE FROM users WHERE username_normalized = ?', (target_norm,))
    db.commit()

    if result.rowcount == 0:
        return jsonify({'error': 'User not found'}), 404

    return jsonify({'message': 'User deleted'}), 200

if __name__ == '__main__':
    init_db()
